// src/enrollments/enrollment.service.ts
@Injectable()
export class EnrollmentService {
  private readonly enrollments = new PgEnrollmentRepository();

  async enroll(userId: string, courseId: string) {
    const now = new Date();
    return this.enrollments.insert({ userId, courseId, enrolledAt: now, expiresAt: addDays(now, 30) });
  }
}

// src/enrollments/enrollment.service.spec.ts
const moduleRef = await Test.createTestingModule({
  providers: [EnrollmentService, { provide: PgEnrollmentRepository, useValue: fakeRepo }],
}).compile();
const service = moduleRef.get(EnrollmentService);
await service.enroll("u1", "c42");

CI output (the unit-test job has no database):
  ● EnrollmentService › enrolls a learner
    Error: connect ECONNREFUSED 127.0.0.1:5432

Statement: "The useValue fake is never used, because EnrollmentService creates its repository with new instead of receiving it through its constructor."', 'single_choice'::question_type, 'True. Nest can only inject what a class asks for through its constructor. EnrollmentService has no constructor parameters, so Nest creates it with no arguments, and the field initializer runs new PgEnrollmentRepository(), which connects to Postgres. The provider { provide: PgEnrollmentRepository, useValue: fakeRepo } is registered, but nothing asks for that token, so it is never used. The fix is constructor(private readonly enrollments: EnrollmentRepository, private readonly clock: Clock) with abstract-class tokens; then the testing module (or a plain new EnrollmentService(fake, fixedClock)) decides what is injected, and the new Date() goes away too. The misconception is that registering a fake in the testing module replaces every use of the class: it replaces only what Nest injects.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nmm_121') AND order_index = 1)
    RETURNING id
)
