    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nmm_121'), 'The clock is extracted so tests can control time:

// src/common/clock.ts
export interface Clock {
  now(): Date;
}

@Injectable()
export class SystemClock implements Clock {
  now(): Date { return new Date(); }
}

// src/enrollments/enrollment.service.ts
@Injectable()
export class EnrollmentService {
  constructor(private readonly clock: Clock) {}
}

// src/enrollments/enrollment.module.ts
@Module({ providers: [EnrollmentService, SystemClock] })
export class EnrollmentModule {}

Statement: "When the application starts, Nest injects SystemClock into EnrollmentService, because SystemClock is the only provider in the module that implements Clock."', 'single_choice'::question_type, 'False. Interfaces are erased when TypeScript compiles, so the constructor metadata records the parameter type as Object, and Nest matches parameters to providers by token, never by which methods a class has. Startup fails with: Nest can''t resolve dependencies of the EnrollmentService (?). Please make sure that the argument Object at index [0] is available in the EnrollmentModule context. The fix is a token that exists at runtime: make Clock an abstract class and register { provide: Clock, useClass: SystemClock }, or keep the interface and use a symbol token, { provide: CLOCK, useClass: SystemClock } with @Inject(CLOCK) on the parameter. The misconception is that Nest wires dependencies by structural typing, the way the TypeScript compiler checks them.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nmm_121') AND order_index = 2)
    RETURNING id
)
