-- challenge chal_coding_nmm_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nmm_122', (SELECT id FROM catalog.course WHERE public_id = 'nestjs-modular-monolith'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nestjs-modular-monolith') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nmm-1-2' AND is_deleted = false LIMIT 1), 'enrollment-service-injected-clock', 'Inject the repository and the clock', 'CodeDev premium access lasts 30 days from the moment a learner enrolls. The old EnrollmentService created its own PgEnrollmentRepository and read the time with new Date(), so it could only be tested against Postgres and failed near midnight. Write EnrollmentService with constructor(repo: EnrollmentRepository, clock: Clock): keep both and use them for everything. Never create a repository and never read the current time with new Date() or Date.now(): the time is clock.now() (new Date(milliseconds) to build a date is fine). Read enrollments from repo on every call, because an admin tool can change the repository between calls. enroll(userId, courseId): throw an Error and save nothing when userId or courseId is empty or only spaces; when the learner already has access, return that enrollment unchanged and save nothing; otherwise (no enrollment, or an expired one) save and return { userId, courseId, enrolledAt: now, expiresAt: now + ACCESS_DAYS (30) days }, both as toISOString() strings. hasAccess(userId, courseId): true when the repository has an enrollment for the pair and now is before expiresAt (at exactly expiresAt, access has ended). daysLeft(userId, courseId): 0 without access, otherwise the time until expiresAt in days rounded up (30 right after enrolling, still 30 one hour later, 1 when less than a day is left). The test runner reads { now, existing, operations } as JSON, builds the service with an in-memory repository holding the existing enrollments and a fixed clock that starts at now and moves only on { op: "advance", hours }, runs enroll, hasAccess, daysLeft and revoke (the admin tool deletes from the repository) in order, and prints one line per call plus the number of save() calls.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
