VALUES ('chal_coding_nmm_212', (SELECT id FROM catalog.course WHERE public_id = 'nestjs-modular-monolith'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nestjs-modular-monolith') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nmm-2-1' AND is_deleted = false LIMIT 1), 'validate-enroll-request', 'Validate the enrollment request', 'POST /enrollments on the CodeDev API stored plan "PREMIUM" because nothing checked the body at runtime, and the nightly billing job could not read the row. In the NestJS app an EnrollDto and the ValidationPipe do this job; the code runner has no NestJS, so write the same rules as one function: validateEnrollRequest(body: unknown) receives the parsed JSON body exactly as the client sent it and returns { ok: true, value } or { ok: false, errors }, where errors holds one { field, message } per invalid field in the order courseId, email, plan, couponCode, seats (the first rule each field fails). "Missing" means the key is absent or null. A body that is not a JSON object (null, an array, a string, a number) gets one error: field "body", message "body must be a JSON object". courseId: missing -> "courseId is required"; not a string -> "courseId must be a string"; not c_ followed by 1 to 9 digits -> "courseId must be c_ followed by 1 to 9 digits". email: missing -> "email is required"; not a string -> "email must be a string"; longer than 254 characters or not matching /^[^\s@]+@[^\s@]+\.[^\s@]+$/ -> "email must be a valid email address". plan: missing -> "plan is required"; not a string -> "plan must be a string"; not exactly "free" or "premium" -> "plan must be one of: free, premium". couponCode is optional (missing = no coupon): not a string -> "couponCode must be a string"; not 4 to 12 characters A-Z or 0-9 -> "couponCode must be 4 to 12 characters, A-Z or 0-9"; a well-formed coupon with plan "free" -> "couponCode is only allowed with plan premium". seats is optional (missing = 1): not a number or not an integer -> "seats must be an integer"; below 1 or above 50 -> "seats must be between 1 and 50". Never convert or trim a value: "PREMIUM", "2" and " c_12" are errors, not guesses. value contains courseId, email, plan, seats and couponCode only when a coupon was given; ignore any other key. Input (stdin): { "bodies": [...] } prints one line per body ("#n ok ..." with every value field, or "#n rejected field: message | ..."); { "generate": { "count", "seed" } } builds bodies with a fixed pseudo-random generator and prints how many were valid and the errors per field.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
