       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nmm_222'), 'The incident: GET /users/:id/profile returns the public profile, never passwordHash or notes', '{"users":[{"id":"u_1","email":"ana@codedev.test","displayName":"Ana","avatarUrl":"https://cdn.codedev.test/avatars/u_1.png","passwordHash":"$argon2id$v=19$m=65536,t=3,p=4$c2FsdA$aGFzaA","internalNotes":"refund issued 2026-09-12","role":"learner","createdAt":"2026-03-14T08:30:00.000Z"},{"id":"u_7","email":"minh@codedev.test","displayName":"Minh","avatarUrl":null,"passwordHash":"$argon2id$v=19$m=65536,t=3,p=4$c2FsdDI$aGFzaDI","internalNotes":"","role":"admin","createdAt":"2025-11-02T17:05:00.000Z"}],"requests":[{"route":"getProfile","params":{"id":"u_1"}}]}', '"#1 GET /users/u_1/profile\n   -> 200 headers={} body={\"avatarUrl\":\"https://cdn.codedev.test/avatars/u_1.png\",\"displayName\":\"Ana\",\"id\":\"u_1\",\"joinedAt\":\"2026-03-14T08:30:00.000Z\"}\n   service: getProfile(u_1)"', 3, true, false, 3),
