       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nmm_222'), 'Unknown user is 404; a null avatarUrl stays null; an admin profile shows no role or email', '{"users":[{"id":"u_1","email":"ana@codedev.test","displayName":"Ana","avatarUrl":"https://cdn.codedev.test/avatars/u_1.png","passwordHash":"$argon2id$v=19$m=65536,t=3,p=4$c2FsdA$aGFzaA","internalNotes":"refund issued 2026-09-12","role":"learner","createdAt":"2026-03-14T08:30:00.000Z"},{"id":"u_7","email":"minh@codedev.test","displayName":"Minh","avatarUrl":null,"passwordHash":"$argon2id$v=19$m=65536,t=3,p=4$c2FsdDI$aGFzaDI","internalNotes":"","role":"admin","createdAt":"2025-11-02T17:05:00.000Z"}],"requests":[{"route":"getProfile","params":{"id":"u_404"}},{"route":"getProfile","params":{"id":"u_7"}}]}', '"#1 GET /users/u_404/profile\n   -> 404 headers={} body={\"error\":\"user not found\"}\n   service: getProfile(u_404)\n#2 GET /users/u_7/profile\n   -> 200 headers={} body={\"avatarUrl\":null,\"displayName\":\"Minh\",\"id\":\"u_7\",\"joinedAt\":\"2025-11-02T17:05:00.000Z\"}\n   service: getProfile(u_7)"', 3, false, true, 6),
