       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nmm_222'), '240 courses: paging through intermediate courses with large and clamped limits', '{"generateCourses":240,"requests":[{"route":"listCourses","query":{"level":"intermediate","page":"2","limit":"50"}},{"route":"listCourses","query":{"level":"intermediate","page":"3","limit":"200"}},{"route":"listCourses","query":{"page":"5","limit":"50"}},{"route":"listCourses","query":{"page":"99"}}]}', '"#1 GET /courses?level=intermediate&page=2&limit=50\n   -> 200 headers={\"X-Total-Count\":\"69\"} body={\"items\":[{\"id\":\"c_176\",\"level\":\"intermediate\",\"priceVnd\":250000,\"title\":\"Course 176\"},{\"id\":\"c_182\",\"level\":\"intermediate\",\"priceVnd\":390000,\"title\":\"Course 182\"},{\"id\":\"c_185\",\"level\":\"intermediate\",\"priceVnd\":460000,\"title\":\"Course 185\"},{\"id\":\"c_188\",\"level\":\"intermediate\",\"priceVnd\":30000,\"title\":\"Course 188\"},{\"id\":\"c_191\",\"level\":\"intermediate\",\"priceVnd\":100000,\"title\":\"Course 191\"},{\"id\":\"c_194\",\"level\":\"intermediate\",\"priceVnd\":170000,\"title\":\"Course 194\"},{\"id\":\"c_197\",\"level\":\"intermediate\",\"priceVnd\":240000,\"title\":\"Course 197\"},{\"id\":\"c_203\",\"level\":\"intermediate\",\"priceVnd\":380000,\"title\":\"Course 203\"},{\"id\":\"c_206\",\"level\":\"intermediate\",\"priceVnd\":450000,\"title\":\"Course 206\"},{\"id\":\"c_209\",\"level\":\"intermediate\",\"priceVnd\":20000,\"title\":\"Course 209\"},{\"id\":\"c_212\",\"level\":\"intermediate\",\"priceVnd\":90000,\"title\":\"Course 212\"},{\"id\":\"c_215\",\"level\":\"intermediate\",\"priceVnd\":160000,\"title\":\"Course 215\"},{\"id\":\"c_218\",\"level\":\"intermediate\",\"priceVnd\":230000,\"title\":\"Course 218\"},{\"id\":\"c_224\",\"level\":\"intermediate\",\"priceVnd\":370000,\"title\":\"Course 224\"},{\"id\":\"c_227\",\"level\":\"intermediate\",\"priceVnd\":440000,\"title\":\"Course 227\"},{\"id\":\"c_230\",\"level\":\"intermediate\",\