INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nmm_232', (SELECT id FROM catalog.course WHERE public_id = 'nestjs-modular-monolith'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nestjs-modular-monolith') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nmm-2-3' AND is_deleted = false LIMIT 1), 'map-domain-errors-to-problems', 'Map domain errors to problem responses', 'Every domain error from the CodeDev enrollment service came back as 500 "Internal server error", so the mobile app retried enrollments that had already failed with a conflict. The service throws typed domain errors and knows nothing about HTTP; write the one function at the edge that turns anything thrown into a response: toProblemResponse(error: unknown, req: { method, path, headers }, newId: () => string) returns { status, headers, body }. Correlation id: use req.headers["x-correlation-id"] when it matches /^[A-Za-z0-9-]{8,64}$/; otherwise call newId() exactly once and use its value (never call it when the header is usable). Headers: { "Content-Type": "application/problem+json", "X-Correlation-Id": id }. Body: { type: "https://api.codedev.test/problems/" + slug, title, status, detail, instance: req.path, correlationId: id } plus extensions. Match with instanceof: CourseNotFound -> 404, slug course-not-found, title "Course not found", detail "Course <courseId> does not exist."; AlreadyEnrolled -> 409, already-enrolled, "Already enrolled", "You are already enrolled in <courseId>."; PrerequisitesMissing -> 422, prerequisites-missing, "Prerequisites missing", "Finish <missing joined by ", "> before enrolling in <courseId>.", extension missing (the list); ValidationFailed -> 400, validation-failed, "Invalid request", "<number of errors> field(s) failed validation.", extension errors: [{ field, message }] (copy only those two keys - the errors may carry the rejected value); NotAllowed -> 403, not-allowed, "Not allowed", "You are not allowed to <action>."; PaymentRequired -> 402, payment-required, "Payment required", "<courseId> requires a premium plan.", extension priceVnd. Anything else - a plain Error or TypeError, a thrown string or null, an object that only looks like a domain error, or a DomainError subclass not in this list - is 500, slug internal-error, title "Internal server error", detail "An unexpected error occurred. Quote the correlation id when you contact support.", and never contains the error''s message. Input (stdin): { "cases": [{ "error": { "kind", ... }, "method"?, "path"?, "correlationId"? }] } (correlationId is sent as the x-correlation-id header; newId() returns gen-0001, gen-0002, ... per test) prints each response with JSON keys sorted; { "generate": { "count", "seed" } } prints the responses per status, the number of newId() calls and how many responses contained internal text.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
