-- challenge chal_coding_nmm_312 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nmm_312', (SELECT id FROM catalog.course WHERE public_id = 'nestjs-modular-monolith'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nestjs-modular-monolith') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nmm-3-1' AND is_deleted = false LIMIT 1), 'enrollment-service-rules', 'EnrollmentService: no duplicates, prerequisites first', 'POST /enrollments on the CodeDev API calls EnrollmentService.enroll(userId, courseId). The shipped version inserted a row for every request, so a double tap and a mobile retry left learners enrolled twice, and the prerequisite check only existed in the web client. Write enroll so the rules live in the service. The repositories are injected through the constructor (in production they are backed by PostgreSQL; here they are in-memory fakes) and, like rows read from a database, every object they return is a copy: a change is stored only when you pass the object to enrollments.save().

Check the rules in this order. 1) courses.findById(courseId) returns undefined: throw new CourseNotFoundError(courseId). 2) The learner has an enrollment in this course with status "active": return { outcome: "existing", enrollment } with that enrollment and check nothing else (a repeated request gets the same answer even if the course was unpublished or its rules changed since). 3) course.published is false: throw new CourseNotPublishedError(courseId). 4) Some courses in course.prerequisites are not completed by the learner (completions.hasCompleted): throw new PrerequisitesMissingError(courseId, missing) with all of them, in the order of course.prerequisites. 5) course.premium is true and entitlements.hasEntitlement(userId, courseId) is false: throw new EntitlementRequiredError(courseId). 6) The learner has a "cancelled" enrollment in this course: set its status to "active", save it and return { outcome: "reactivated", enrollment } (same id, never a second row). 7) Otherwise return { outcome: "created", enrollment: enrollments.create(userId, courseId) }.

Input (stdin): { "courses": [{ id, published, premium, prerequisites }], "completions": [[userId, courseId]], "entitlements": [[userId, courseId]], "enrollments": [{ id, userId, courseId, status }], "operations": [{ "op": "enroll" | "cancel", userId, courseId }], "summary"?: true }. Ids are compared exactly (no trimming, case-sensitive). "cancel" is done by the test runner on the repository. Output: one line per operation (the outcome with the enrollment id and status, or "error <code>" with the missing prerequisites in brackets), then every enrollment row ordered by id; with summary, only the count per outcome or error code and the number of active and cancelled rows. Do not change the types, error classes, repositories or test runner.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
