-- lesson 3.2: Progress that never goes backwards: idempotent updates (Sanity lesson-nmm-3-2)
UPDATE course.lesson SET title = 'Progress that never goes backwards: idempotent updates', order_index = 2, module_id = (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nestjs-modular-monolith') AND order_index = 3 AND is_deleted = false LIMIT 1), updated_at = now() WHERE id = (SELECT id FROM course.lesson WHERE content_source = 'lesson-nmm-3-2' AND is_deleted = false LIMIT 1);
INSERT INTO course.lesson (module_id, title, content_type, content_source, order_index)
SELECT (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nestjs-modular-monolith') AND order_index = 3 AND is_deleted = false LIMIT 1), 'Progress that never goes backwards: idempotent updates', 'sanity', 'lesson-nmm-3-2', 2
WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-nmm-3-2' AND is_deleted = false);

-- challenge chal_quiz_nmm_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nmm_321', (SELECT id FROM catalog.course WHERE public_id = 'nestjs-modular-monolith'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nestjs-modular-monolith') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nmm-3-2' AND is_deleted = false LIMIT 1), 'idempotent-progress-quiz', 'Which part of progress is idempotent?', 'Two fixes proposed after progress went from 80% back to 40% and a learner got two certificates: a GREATEST update, and an event table that remembers every eventId.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nmm_321');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nmm_321');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nmm_321'), 'First fix proposed in the review:

// progress.repository.ts
UPDATE lesson_progress SET percent = GREATEST(percent, $4)
WHERE user_id = $1 AND course_id = $2 AND lesson_id = $3;

// progress.service.ts
await this.progress.raise(userId, courseId, lessonId, percent);
const coursePercent = await this.progress.coursePercent(userId, courseId);
if (coursePercent === 100) await this.certificates.issue(userId, courseId);

API log for one learner:

14:02:10.481 POST /progress/events ev_802 whf-10 100 -> 200 (2.4 s, client timed out)
14:02:12.903 POST /progress/events ev_802 whf-10 100 -> 200 (retry)

Statement: "Because the update uses GREATEST, this code can no longer issue two certificates when the final event is retried."', 'single_choice'::question_type, 'False. GREATEST makes the stored progress idempotent: the retry cannot lower or change the percent. But the certificate is a side effect, and this code runs it after every event that finds the course at 100%, including the retry of ev_802 and any later stale event for that course. Exactly-once needs its own guard: publish only when this event moved the course from below 100 to 100, remember processed eventIds, and in the database a unique constraint on certificates (user_id, course_id) as the last line of defence. The misconception is that an idempotent state update makes everything that follows it idempotent too.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nmm_321') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nmm_321'), 'Second fix, in one transaction per event:

BEGIN;
INSERT INTO processed_events (event_id, received_at) VALUES ($1, now())
  ON CONFLICT (event_id) DO NOTHING
  RETURNING event_id;
-- no row returned: ROLLBACK and answer { status: "duplicate" }
-- one row returned: raise the lesson percent, check for completion, COMMIT

processed_events.event_id is the primary key. The mobile app''s offline queue and its retry deliver ev_802 twice, 4 ms apart, to two API instances.

Statement: "Even though both deliveries run at the same time, only one of them gets a row back from the INSERT, so the progress update and the completion check run once for ev_802."', 'single_choice'::question_type, 'True. The primary key makes the second INSERT of the same event_id wait for the first transaction. When the first commits, the second sees the conflict, does nothing and returns no row, so it answers duplicate without touching progress. If the first rolled back, the second would insert and process the event, which is also correct: the event then counts exactly once. This is why the eventId check belongs in the same transaction as the update, enforced by a key, and not in a separate SELECT before it, which two concurrent deliveries could both pass. The misconception is that an in-memory or SELECT-then-INSERT check gives the same guarantee across several API instances.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nmm_321') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_nmm_322 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nmm_322', (SELECT id FROM catalog.course WHERE public_id = 'nestjs-modular-monolith'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nestjs-modular-monolith') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nmm-3-2' AND is_deleted = false LIMIT 1), 'idempotent-progress-service', 'ProgressService: duplicates, late events and one completion', 'The CodeDev mobile app sends a progress event while a learner reads or watches a lesson: { eventId, userId, courseId, lessonId, percent }. It keeps unsent events in an offline queue and retries a request after a timeout, so the same event can arrive twice and an older event can arrive after a newer one. The shipped ProgressService stored the last value it received, so a slow older event moved a lesson from 80% back to 40%, and a retried final event issued a second completion certificate. Write ProgressService.record(event) so that progress never goes backwards and the completion is published exactly once. Its stores are injected through the constructor: in-memory fakes here, PostgreSQL tables in production.

Rules. Invalid: eventId and userId must be non-empty strings, catalog.lessonIds(courseId) must return a list that contains lessonId, and percent must be an integer from 0 to 100 (the events come from JSON, so check the values at runtime). Otherwise return { status: "invalid" } and change nothing - do not remember its eventId. Duplicate: processed.has(eventId) -> { status: "duplicate" }, nothing changes. Stale: percent is not higher than the stored percent of that lesson (a lesson with nothing stored counts as 0) -> { status: "stale", lessonPercent: <stored>, coursePercent }. Applied: otherwise store the percent -> { status: "applied", lessonPercent, coursePercent, courseCompleted }. Every valid event, applied or stale, is remembered with processed.add(eventId). coursePercent is Math.floor(sum of the stored percents of every lesson of the course / number of lessons), with missing lessons counted as 0. When an event moves coursePercent from below 100 to 100, call bus.publish({ type: "course.completed", userId, courseId }) once and return courseCompleted: true; in every other case courseCompleted is false and nothing is published.

Input (stdin): { "courses": { courseId: lessonId[] }, "progress"?: [[userId, courseId, lessonId, percent]], "processed"?: [eventId], "events": [event], "summary"?: true }. progress and processed describe the state before the first event (for example, events stored before a restart). Output: one line per event with its status and percentages, the published events, and the stored percent of every lesson per learner and course; with summary, the count per status, the number of published events, the number of stored lessons and the sum of their percents. Do not change the types, the stores or the test runner.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nmm_322');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nmm_322'), 1, 'For one incoming event, what has to be true for it to change anything at all - and among the events that do change something, which single one is allowed to announce that the course is finished?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nmm_322'), 2, 'Look at three moments: before anything is stored (is the event valid, has its eventId been seen), the comparison between the incoming percent and the stored one, and the course percentage computed before and after the store. The completion depends on both of those course percentages, not only on the one after.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nmm_322'), 3, 'The same shape for a reading streak: events { eventId, day } where the streak may only grow. Event r1 day 5 on a stored day 3 -> stored 5, applied; r0 day 4 arriving late -> stays 5, stale; r1 again -> duplicate. A 7-day badge is awarded when the streak goes from 6 to 7, so a later event that finds the streak at 9 awards nothing, and neither does a retry.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nmm_322'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
