WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-nmm-3-3' AND is_deleted = false);

-- challenge chal_quiz_nmm_331 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nmm_331', (SELECT id FROM catalog.course WHERE public_id = 'nestjs-modular-monolith'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nestjs-modular-monolith') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nmm-3-3' AND is_deleted = false LIMIT 1), 'persistence-boundary-quiz', 'Ports, adapters and injection tokens', 'Three pieces of evidence from moving EnrollmentModule behind a repository port: a test that swaps the PostgreSQL adapter, a startup error, and a leaderboard query that broke after a migration in another module.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
