WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nmm_331'), '// src/enrollments/enrollment.module.ts
providers: [
  EnrollmentService,
  { provide: ENROLLMENT_REPOSITORY, useClass: PgEnrollmentRepository },
],

// src/enrollments/enrollment.service.ts
constructor(
  @Inject(ENROLLMENT_REPOSITORY) private readonly enrollments: EnrollmentRepository,
  private readonly courses: CourseService,
) {}

// test/enrollment.module.spec.ts
const moduleRef = await Test.createTestingModule({ imports: [EnrollmentModule] })
  .overrideProvider(ENROLLMENT_REPOSITORY).useValue(new InMemoryEnrollmentRepository())
  .overrideProvider(CourseService).useValue(fakeCourses)
  .compile();
const service = moduleRef.get(EnrollmentService);

Statement: "In this test, EnrollmentService receives the in-memory repository, and nothing in EnrollmentService had to change for that."', 'single_choice'::question_type, 'True. EnrollmentService asks for whatever is registered under the token ENROLLMENT_REPOSITORY and only knows the EnrollmentRepository interface. overrideProvider replaces the registration for that token in the testing module, so Nest injects the InMemoryEnrollmentRepository instead of PgEnrollmentRepository, with no change to the service, its module or its constructor. That is the point of the port: the service depends on what it needs (find, create, save), and the module decides which adapter provides it. The misconception is that the service has to be written with a test mode or a flag to be testable without a database.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nmm_331') AND order_index = 1)
    RETURNING id
)
